css:
/* 卷轴：滚动模板。页眉页脚固定（不参与滚动），仅 .ps-viewport 滚动；正文区 ≥80% 页高 */
:root{
  --ps-bg:#efe9dd; --ps-fg:#332c22; --ps-dim:#7d7365; --ps-line:#cfc5b3; --ps-accent:#8a6d3b;
}
[data-reader-theme="night"]{
  --ps-bg:#191713; --ps-fg:#d8d2c6; --ps-dim:#8d8578; --ps-line:#3a352c; --ps-accent:#c8a76a;
}
html,body{margin:0;padding:0;height:100%;background:var(--ps-bg);color:var(--ps-fg);
  font-family:-apple-system,"Noto Serif CJK SC","Source Han Serif SC",serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.85);overflow:hidden;}
.ps-shell{display:flex;flex-direction:column;height:100vh;}
.ps-head,.ps-foot{flex:0 0 auto;display:flex;align-items:center;gap:.6em;
  padding:.6em 1.1em;font-size:.76em;color:var(--ps-dim);letter-spacing:.06em;}
.ps-head{border-bottom:1px solid var(--ps-line);}
.ps-foot{border-top:1px solid var(--ps-line);justify-content:space-between;font-variant-numeric:tabular-nums;}
.ps-head span:first-child{color:var(--ps-accent);}
.ps-viewport{flex:1 1 auto;overflow-y:auto;overflow-x:hidden;padding:1em 1.3em 0;
  -webkit-overflow-scrolling:touch;}
.ps-body p{margin:0 0 1em;}
.ps-body .reader-paragraph{text-indent:2em;}
.ps-body .reader-chapter-title{margin:.2em 0 1em;font-size:1.3em;letter-spacing:.04em;}
.ps-body a{color:var(--ps-accent);text-decoration:none;}
.ps-body blockquote{margin:0 0 1em;padding:.4em .9em;border-left:2px solid var(--ps-line);color:var(--ps-dim);}
.ps-body code{font-family:"JetBrains Mono",Consolas,monospace;font-size:.9em;
  background:rgba(127,127,127,.12);padding:.12em .32em;border-radius:3px;}
.ps-body pre{background:rgba(127,127,127,.1);padding:.8em;border-radius:4px;overflow-x:auto;}
.ps-body table{width:100%;border-collapse:collapse;}
.ps-body th,.ps-body td{border:1px solid var(--ps-line);padding:.35em .55em;}
.ps-tail{height:12vh;background:linear-gradient(180deg,transparent,var(--ps-line));opacity:.35;}
